def backend_list(svc):
    """The backends the account exposes through the instance, by name only."""
    return sorted(b.name for b in svc.backends())


def window():
    w = json.loads((HERE / "window-t20.json").read_text())["window"]
    if not w.get("applies"):
        return None
    f = lambda s: datetime.fromisoformat(s.replace("Z", "+00:00"))
    return f(w["from_utc"]), f(w["to_utc"])


def in_window(t=None):
    t = t or datetime.now(timezone.utc)
    w = window()
    return bool(w) and w[0] <= t <= w[1]


# --------------------------------------------------------------------------- the calibration record (hw_t7)
def record_stamp(backend, kind, job_status="", refresh=True):
    """Read the backend's properties, save the snapshot if its stamp is new, compare it by value with the previous one
    (history 01's compare and other_changes), and append a row to stamps-t20.csv. (hw_t7.record_stamp.)"""
    STAMPS.mkdir(exist_ok=True)
    p = backend.properties(refresh=refresh)
    s = p.last_update_date.astimezone(timezone.utc)
    name = f"snapshot-{s.strftime('%Y%m%dT%H%M%SZ')}.json"
    path = STAMPS / name
    rows_p = HERE / "stamps-t20.csv"
    rows = list(csv.DictReader(rows_p.open())) if rows_p.exists() else []
    seen = [r["snapshot"] for r in rows]
    new = name not in seen
    row = {"utc": now(), "kind": kind, "stamp_utc": s.strftime("%Y-%m-%dT%H:%M:%SZ"), "stamp_raw": str(p.last_update_date),
           "new_stamp": new, "job_status": job_status, "snapshot": name}
    if not path.exists():
        path.write_text(json.dumps(p.to_dict(), default=str, indent=1) + "\n")
    if new and seen:
        prev = STAMPS / seen[-1]
        c = TH.compare(TH.load(prev), TH.load(path))
        o = TH.other_changes(prev, path)
        row.update({"q_T1": c["q_T1"], "q_T2": c["q_T2"], "q_readout_error": c["q_readout_error"], "g1_any": c["g1_any"],
                    "cz_error": c["cz_error"], "cz_length": c["cz_length"], "other_values_changed": o["other_values_changed"],
                    "any_value_changed": o["any_value_changed"]})
    row.update(qubit_published(p))
    with rows_p.open("a", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=STAMP_FIELDS)
        if not rows:
            w.writeheader()
        w.writerow(row)
    return row


def qubit_published(p):
    """143's published readout error, P(1|0), P(0|1), T1 and T2 (us) at this read, and the published P(1|0) of 142 and
    144. (hw_t7.qubit_published.)"""
    def qp(q, name, scale=1.0):
        try:
            v = p.qubit_property(q).get(name, (None,))[0]
            return None if v is None else round(float(v) * scale, 6)
        except Exception:
            return None

    return {"q143_readout_error": qp(QUBIT, "readout_error"), "q143_prob_meas1_prep0": qp(QUBIT, "prob_meas1_prep0"),
            "q143_prob_meas0_prep1": qp(QUBIT, "prob_meas0_prep1"), "q143_T1_us": qp(QUBIT, "T1", 1e6),
            "q143_T2_us": qp(QUBIT, "T2", 1e6), "q142_prob_meas1_prep0": qp(142, "prob_meas1_prep0"),
            "q144_prob_meas1_prep0": qp(144, "prob_meas1_prep0")}


def cycle_check(row, t=None):
    """t20-rule.md section 2 ("as test 7's rule states"): no job is submitted while the day's cycle is in progress, from
    a stamp at which T1 changed on more than half the qubits until 30 minutes after the next stamp at which CZ errors
    changed on more than half the edges. (hw_t7.cycle_check, unchanged in what it does.)"""
    t = t or datetime.now(timezone.utc)
    cyc = json.loads((HERE / "window-t20.json").read_text())["cycle"]
    out = {"utc": now(), "latest_T1_stamp_utc": cyc["latest_T1_stamp_utc"], "latest_CZ_stamp_utc": cyc["latest_CZ_stamp_utc"],
           "cycle_complete_in_48h": cyc["cycle_complete_in_48h"], "submissions_from_utc": cyc["submissions_from_utc"], "snapshot_read": row["snapshot"]}
    f = lambda s: datetime.fromisoformat(s.replace("Z", "+00:00"))
    if cyc["latest_T1_stamp_utc"] is None:
        # no stamp in the 48 hours changed T1 on more than half the qubits: the reading is the author's
        if CYCLE_NO_T1_STAMP_READING != "no cycle, no bar":
            return {**out, "pass": False, "reason": "no T1 stamp in the 48 hours; the author's reading for this case is not recorded"}
        w = json.loads((HERE / "window-t20.json").read_text())
        base = sorted((HERE / "history-t20" / "snapshots").glob("snapshot-*.json"))[-1]
        c = TH.compare(TH.load(base), TH.load(STAMPS / row["snapshot"]))
        since = {"q_T1": c["q_T1"], "cz_error": c["cz_error"], "n_edges": c["n_edges"], "from_snapshot": base.name}
        new_cycle = c["q_T1"] > TH.N_QUBITS / 2
        return {**out, "reading": CYCLE_NO_T1_STAMP_READING, "changed_since_walk_end": since, "new_cycle_since_walk": new_cycle,
                "pass": not new_cycle,
                "reason": "a T1 step on more than half the qubits since the walk: a cycle is in progress" if new_cycle
                else "no T1 stamp in the 48 hours and none since: no cycle in progress (the author's reading)"}
    if not cyc["cycle_complete_in_48h"]:
        return {**out, "pass": False, "reason": "the walk's latest T1 stamp has no CZ stamp after it"}
    if t < f(cyc["submissions_from_utc"]):
        return {**out, "pass": False, "reason": "less than 30 minutes after the latest CZ stamp"}
    cz_snap = HERE / "history-t20" / "snapshots" / f"snapshot-{f(cyc['latest_CZ_stamp_utc']).strftime('%Y%m%dT%H%M%SZ')}.json"
    c = TH.compare(TH.load(cz_snap), TH.load(STAMPS / row["snapshot"]))
    since = {"q_T1": c["q_T1"], "cz_error": c["cz_error"], "n_edges": c["n_edges"]}
    new_cycle = c["q_T1"] > TH.N_QUBITS / 2 or c["cz_error"] > c["n_edges"] / 2
    return {**out, "changed_since_latest_CZ_stamp": since, "new_cycle_since_walk": new_cycle, "pass": not new_cycle,
            "reason": "a new T1 or CZ step since the walk's latest CZ stamp" if new_cycle else "the day's cycle is complete and no new step has come"}


# --------------------------------------------------------------------------- the circuits (hw_t7)
def made(qc, chain, backend, name):
    ins, isa = K51._made(qc, chain, backend)
    return K50.rebuild(isa, ins, name)


def readout_circuit(k, M, backend):
    """The two readout circuits on M alone, outside the package: P10 measures with no gate (P(1|0)); P01 applies X,
    then measures (P(0|1)). (hw_t7.readout_circuit.)"""
    from qiskit import QuantumCircuit
    qc = QuantumCircuit(1, 1, name=f"{k}-{M}")
    if k == "P01":
        qc.x(0)
    qc.measure(0, 0)
    return made(qc, [M], backend, f"{k}-{M}")


def wait_dt_of(t_us, backend):
    g = getattr(backend.target, "granularity", 1) or 1
    return W.even_wait(t_us * 1e-6 / backend.dt, g), g


def logical_ramsey(quad, wait_dt):
    """X: the package's Part B Ramsey on one qubit, H, the wait, H, measure. Y: the same with an S-dagger inserted on the
    qubit right before the final H. (hw_t7.logical_ramsey.)"""
    qc = W.part_b_circuit(1, wait_dt, "R")
    if quad == "Y":
        from qiskit.circuit import CircuitInstruction
        from qiskit.circuit.library import SdgGate
        k = max(i for i, x in enumerate(qc.data) if x.operation.name == "h")
        qc.data.insert(k, CircuitInstruction(SdgGate(), (qc.qubits[0],)))
        qc.name = f"Y{wait_dt}"
    return qc


def scheduled_wait(c, backend):
    """The wait as scheduled on 143: from the end of its first sx to the start of its last (hw_t7.scheduled_wait)."""
    sch = W.scheduled(c, backend.target)
    ins = [x for x in K50.instructions(sch) if set(x[1]) <= {QUBIT}]
    tl = K50.timed(ins, backend.target, backend.dt, [QUBIT])
    w = K50.window(tl, QUBIT)
    delays = [int(op.duration) for op, qs, _ in K50.instructions(c) if op.name == "delay" and qs == [QUBIT]]
    return {"T_dt": int(w["T_dt"]), "T_us": w["T_dt"] * backend.dt * 1e6, "n_sx": w["n_sx"], "delays_on_143_dt": delays}


def build(backend, waits_us):
    """X(t) and Y(t) at each wait, and P10 and P01, on 143 alone (hw_t7.build, the waits given)."""
    circ, info = {}, {}
    for t in waits_us:
        wdt, g = wait_dt_of(t, backend)
        for quad in QUADS:
            lg = logical_ramsey(quad, wdt)
            isa = W.to_backend(lg, [QUBIT], backend)
            circ[(quad, t)] = isa
            info[(quad, t)] = {"t_requested_us": t, "requested_dt": t * 1e-6 / backend.dt, "wait_dt": wdt, "granularity": g,
                               "logical": W.structure(lg), "scheduled": scheduled_wait(isa, backend)}
    for k in READOUT:
        circ[(k, None)] = readout_circuit(k, QUBIT, backend)
        info[(k, None)] = {}
    return circ, info


def ops_of(c, q=None):
    out = []
    for i in c.data:
        qs = [c.find_bit(x).index for x in i.qubits]
        if q is not None and q not in qs:
            continue
        out.append((i.operation.name, qs, [c.find_bit(x).index for x in i.clbits]))
    return out


def digest(c):
    """A hash of every instruction in order: name, qubits, clbits and parameters (hw_61.digest)."""
    def par(op):
        try:
            return [round(float(x), 12) for x in op.params]
        except Exception:
            return [str(x) for x in op.params]
    seq = [(i.operation.name, [c.find_bit(x).index for x in i.qubits], [c.find_bit(x).index for x in i.clbits], par(i.operation)) for i in c.data]
    return hashlib.sha256(json.dumps(seq).encode()).hexdigest()


def exact_p1(c):
    p = W.exact_distribution(c)
    return float(sum(v for key, v in p.items() if key[-1] == "1"))


def checks(circ, info):
    """The structural checks per circuit (hw_t7.checks). Returns (records, all pass)."""
    recs, ok = {}, True
    for (k, t), c in circ.items():
        name = f"{k}|{t}"
        r = {}
        used = {q for _, qs, _ in ops_of(c) for q in qs}
        r["every_instruction_on_143"] = used == {QUBIT}
        r["one_clbit_measured_once"] = c.num_clbits == 1 and sum(1 for nm, _, _ in ops_of(c) if nm == "measure") == 1
        r["no_two_qubit_gate"] = all(len(qs) == 1 for _, qs, _ in ops_of(c))
        p1 = exact_p1(c)
        r["exact_p1"] = p1
        if k in QUADS:
            i = info[(k, t)]
            seq = K51.m_sequence(c, QUBIT)
            r["m_sequence"] = seq
            x_seq = K51.m_sequence(circ[("X", t)], QUBIT)
            if k == "X":
                r["is_H_wait_H_measure"] = [n for n, _ in seq] == ["rz", "sx", "rz", "rz", "sx", "rz", "measure"]
            else:
                r["is_X_with_one_rz_minus_90_before_the_last_H"] = seq == x_seq[:3] + [("rz", -90.0)] + x_seq[3:]
            r["delay_is_wait_dt"] = i["scheduled"]["delays_on_143_dt"] == ([i["wait_dt"]] if i["wait_dt"] else [])
            r["scheduled_is_wait_dt"] = i["scheduled"]["T_dt"] == i["wait_dt"]
            r["two_sx"] = i["scheduled"]["n_sx"] == 2
            r["wait_even"] = i["wait_dt"] % 2 == 0
            r["exact_as_expected"] = abs(p1 - (0.0 if k == "X" else 0.5)) < 1e-9
        else:
            r["exact_as_expected"] = abs(p1 - (0.0 if k == "P10" else 1.0)) < 1e-9
            r["gates"] = [nm for nm, _, _ in ops_of(c, QUBIT) if nm not in ("delay", "barrier")]
        good = all(v for v in r.values() if isinstance(v, bool))
        r["pass"] = good
        ok = ok and good
        recs[name] = r
    return recs, ok


def label_of(job, pos, k, t, info, dt, cp=None, repeat=None, block=None):
    """Job 1: test 7's label exactly (hw_t7.label_of), with no position or job field, so that the copies of a circuit
    carry the same label but for "copy" (manacitra.wait.copies_check groups them so). Jobs 2 and 3: the position, the
    repeat and the block, as hw_t10 labels the monitor."""
    if job == 1:
        if k in QUADS:
            i = info[(k, t)]
            return {"circuit": k, "quadrature": k, "t_requested_us": t, "wait_dt": i["wait_dt"], "scheduled_wait_dt": i["scheduled"]["T_dt"],
                    "scheduled_wait_us": i["scheduled"]["T_dt"] * dt * 1e6, "copy": cp, "qubit": QUBIT, "clbit": 0,
                    "built_by": "package: part_b_circuit(1, wait_dt, 'R'), to_backend on [143]" + (", with an SdgGate inserted before the final H" if k == "Y" else "")}
        return {"circuit": k, "quadrature": None, "t_requested_us": None, "copy": cp, "qubit": QUBIT, "clbit": 0,
                "built_by": "outside the package (readout on 143 alone, Kickoff 62's readout_circuit, translated by to_backend)"}
    lab = {"job": job, "position": pos, "circuit": k, "quadrature": k if k in QUADS else None, "repeat": repeat, "block": block, "qubit": QUBIT, "clbit": 0}
    if k in QUADS:
        i = info[(k, t)]
        lab.update({"t_requested_us": t, "wait_dt": i["wait_dt"], "scheduled_wait_dt": i["scheduled"]["T_dt"],
                    "scheduled_wait_us": i["scheduled"]["T_dt"] * dt * 1e6,
                    "built_by": "package: part_b_circuit(1, wait_dt, 'R'), to_backend on [143]" + (", with an SdgGate inserted before the final H" if k == "Y" else "")})
    else:
        lab.update({"t_requested_us": None, "built_by": "outside the package (readout on 143 alone, Kickoff 62's readout_circuit, translated by to_backend)"})
    return lab


# --------------------------------------------------------------------------- the order of each job
def order_j1():
    """Every circuit and copy in one random order: numpy.random.default_rng(20301).permutation (hw_t7.assemble)."""
    keys = [("X", t) for t in WAITS_US] + [("Y", t) for t in WAITS_US] + [(k, None) for k in READOUT]
    items = [(key, cp) for key in keys for cp in range(1, COPIES + 1)]
    perm = np.random.default_rng(ORDER_SEED_J1).permutation(len(items))
    return [items[i] for i in perm]


def order_mon():
    """The rule's 300 positions: (circuit, repeat or None, block) (hw_t10.monitor_order)."""
    out = [(k, None, "start") for k in READOUT]
    for r in range(1, N_REP + 1):
        out += [("X", r, "monitor"), ("Y", r, "monitor")]
    return out + [(k, None, "end") for k in READOUT]


def assemble(job, circ, info, dt):
    circs, labels, shots = [], [], []
    if job == 1:
        for pos, ((k, t), cp) in enumerate(order_j1()):
            circs.append(circ[(k, t)])
            labels.append(label_of(1, pos, k, t, info, dt, cp=cp))
            shots.append(SHOTS_J1)
    else:
        for pos, (k, r, block) in enumerate(order_mon()):
            t = MON_WAIT_US if k in QUADS else None
            circs.append(circ[(k, t)])
            labels.append(label_of(job, pos, k, t, info, dt, repeat=r, block=block))
            shots.append(SHOTS_MON)
    return circs, labels, shots


def order_checks(job, circ, circs, labels, shots):
    """The positions in the rule's order, rebuilt independently of assemble(): job 1, the permutation of seed 20301 over
    the 260 (circuit, copy) items in test 7's item order, each circuit twice; jobs 2 and 3, P10, P01, 148 repeats of X
    then Y, P10, P01."""
    dig = {key: digest(c) for key, c in circ.items()}
    pos_dig = [digest(c) for c in circs]
    if job == 1:
        keys = [("X", t) for t in WAITS_US] + [("Y", t) for t in WAITS_US] + [(k, None) for k in READOUT]
        items = [(key, cp) for key in keys for cp in (1, 2)]
        want = [items[i] for i in np.random.default_rng(20301).permutation(260)]
        r = {"n_positions": len(circs), "n_positions_is_260": len(circs) == N_POSITIONS_J1,
             "labels_in_the_seed_20301_order": [((l["circuit"], l["t_requested_us"]), l["copy"]) for l in labels] == want,
             "each_position_carries_its_labels_circuit": pos_dig == [dig[key] for key, cp in want],
             "each_circuit_twice": all(sum(1 for key, cp in want if key == k) == 2 for k in keys),
             "copies_share_one_label_but_for_copy": all(len({json.dumps({a: b for a, b in l.items() if a != "copy"}, sort_keys=True)
                                                              for l in labels if (l["circuit"], l["t_requested_us"]) == k}) == 1 for k in keys),
             "one_shot_count": set(shots) == {SHOTS_J1}, "shots_total": sum(shots), "interleaving_seed": ORDER_SEED_J1}
    else:
        want = order_mon()
        key_of = lambda k: (k, MON_WAIT_US if k in QUADS else None)
        r = {"n_positions": len(circs), "n_positions_is_300": len(circs) == N_POSITIONS_MON,
             "labels_in_the_rules_order": [(l["circuit"], l["repeat"], l["block"]) for l in labels] == [tuple(x) for x in want],
             "each_position_carries_its_labels_circuit": pos_dig == [dig[key_of(k)] for k, rr, b in want],
             "every_repeat_X_then_Y": all(labels[2 + 2 * (k - 1)]["circuit"] == "X" and labels[3 + 2 * (k - 1)]["circuit"] == "Y" for k in range(1, N_REP + 1)),
             "readout_first_and_last": [l["circuit"] for l in labels[:2]] == list(READOUT) and [l["circuit"] for l in labels[-2:]] == list(READOUT),
             "positions_numbered_in_order": [l["position"] for l in labels] == list(range(len(labels))),
             "one_shot_count": set(shots) == {SHOTS_MON}, "shots_total": sum(shots),
             "note": "not interleaved; the sampler is given the list as (circuit, None, shots) in this order"}
    r["pass"] = all(v for v in r.values() if isinstance(v, bool))
    return r


def digests(circ):
    return {f"{k}|{t}": digest(c) for (k, t), c in circ.items()}


def limits(b, circs, shots):
    cfg = b.configuration()
    used = set().union(*[set(c.count_ops()) for c in circs])
    return {"max_shots": cfg.max_shots, "max_experiments": cfg.max_experiments, "n_positions": len(circs),
            "within": max(shots) <= cfg.max_shots and len(circs) <= cfg.max_experiments,
            "instructions_not_in_target": sorted(used - set(b.target.operation_names) - {"barrier", "delay"})}


def built(b, job):
    waits = WAITS_US if job == 1 else (MON_WAIT_US,)
    circ, info = build(b, waits)
    recs, ok = checks(circ, info)
    circs, labels, shots = assemble(job, circ, info, b.dt)
    order = order_checks(job, circ, circs, labels, shots)
    lim = limits(b, circs, shots)
    wrec = [{"t_requested_us": t, "requested_dt": info[("X", t)]["requested_dt"], "wait_dt": info[("X", t)]["wait_dt"],
             "scheduled_dt": {q: info[(q, t)]["scheduled"]["T_dt"] for q in QUADS},
             "scheduled_us": {q: info[(q, t)]["scheduled"]["T_us"] for q in QUADS},
             "difference_us": {q: info[(q, t)]["scheduled"]["T_us"] - t for q in QUADS}} for t in waits]
    n_pos = N_POSITIONS_J1 if job == 1 else N_POSITIONS_MON
    ok = ok and order["pass"] and lim["within"] and not lim["instructions_not_in_target"] and len(circs) == n_pos
    return circ, info, recs, circs, labels, shots, lim, wrec, order, ok


def estimate(job, n_shots):
    """The rule's estimate: the measured rate per shot of the most recent job of the same design times the shots, with
    the half-again margin and IBM's published formula beside."""
    s = RATE[job]["s_per_shot"] * n_shots
    return {"shots": n_shots, "rate_s_per_shot": RATE[job]["s_per_shot"], "rate_from": RATE[job]["from"], "expected_s": s,
            "with_margin_s": 1.5 * s, "beside_ibm_formula_s": 2 + 0.35e-3 * n_shots, "beside_ibm_formula_note": "2 s per job + 0.35 ms per shot",
            "beside_earlier_measured_s": DAY2_RATE[job]["s_per_shot"] * n_shots, "beside_earlier_measured_from": DAY2_RATE[job]["from"]}


def shots_of(job):
    return N_POSITIONS_J1 * SHOTS_J1 if job == 1 else N_POSITIONS_MON * SHOTS_MON


def sampler_for(b, job):
    smp = K50.make_sampler(b)
    smp.options.environment.job_tags = [TAGS[job]]
    so = smp.options
    sopt = {"dynamical_decoupling_enable": so.dynamical_decoupling.enable, "twirling_enable_gates": so.twirling.enable_gates,
            "twirling_enable_measure": so.twirling.enable_measure, "job_tags": list(so.environment.job_tags)}
    good = (sopt["dynamical_decoupling_enable"] is False and sopt["twirling_enable_gates"] is False
            and sopt["twirling_enable_measure"] is False and sopt["job_tags"] == [TAGS[job]])
    return smp, sopt, good


def summary(recs):
    bad = [k for k, r in recs.items() if not r["pass"]]
    return {"circuits": len(recs), "failing": bad}


# --------------------------------------------------------------------------- the inputs


def meta():
    import qiskit
    import qiskit_ibm_runtime
    return {"script_sha256": sha(__file__), "qiskit": qiskit.__version__, "qiskit_ibm_runtime": qiskit_ibm_runtime.__version__,
            "numpy": np.__version__, "manacitra_commit": COMMIT, "manacitra_version_string": manacitra.__version__,
            "manacitra_wait_sha256": sha(HERE / "site/manacitra/wait.py"), "utc": now()}


# --------------------------------------------------------------------------- the decision, before each build
def final_status_of(job):
    """'DONE' if the job's counts are saved, 'ERROR' or 'CANCELLED' if its failure is recorded, 'REFUSED' if its recorded
    decision is that it does not run (ruling 3), else None."""
    if recorded(f"results-t20-job{job}-counts.json"):
        return "DONE"
    d = recorded(f"decision-t20-job{job}.json")
    if d and not d["decision"]["runs"]:
        return "REFUSED"
    f = recorded(f"failed-t20-job{job}.json")
    return f["status"] if f else None


def write_decision(job):
    """decision-t20-job{job}.json, recorded before the job is built: the allowance read with its UTC time, the job's
    estimate with the half-again margin, and whether the job runs (t20-rule.md section 2: the allowance clause over all
    three estimates before job 1; after job 1, only if the job's estimate with the margin is within the allowance). Jobs 2 and 3 are decided only after the previous job reached a final status."""
    p = HERE / f"decision-t20-job{job}.json"
    if p.exists():
        sys.exit("refusing: the decision is recorded")
    if job > 1 and final_status_of(job - 1) is None:
        sys.exit(f"STOP: job {job - 1} has not reached a recorded final status; job {job} is not decided")
    svc = service()
    u = usage(svc)
    est = estimate(job, shots_of(job))
    rem = None if u["remaining_s"] is None else float(u["remaining_s"])
    within = rem is not None and est["with_margin_s"] <= rem
    margins = {j: estimate(j, shots_of(j))["with_margin_s"] for j in (1, 2, 3)}
    if job == 1:
        # t20-rule.md section 2, "The allowance, and which job gives way", read before job 1
        if rem is not None and rem >= margins[1] + margins[2] + margins[3]:
            plan, runs, why = "ALL THREE", True, "the allowance covers all three estimates with their margins: all three run in order"
        elif rem is not None and rem >= margins[2] + margins[3]:
            plan, runs, why = "MONITORS ONLY", False, "the allowance covers the two monitors with their margins but not the scan as well: the scan is not run; R0 is 0.4770 and question 1 reports no verdict"
        elif rem is not None and rem >= margins[2]:
            plan, runs, why = "JOB 2 ALONE", False, "the allowance covers less than the two monitors: job 2 runs alone, read as test 18's rule reads a single job"
        else:
            plan, runs, why = "NOTHING", False, "the allowance does not cover job 2's estimate with its margin: nothing is submitted"
    else:
        plan = recorded("decision-t20-job1.json")["decision"]["plan"]
        if plan == "NOTHING" or (job == 3 and plan == "JOB 2 ALONE"):
            runs, why = False, f"the plan recorded before job 1 is {plan}: job {job} does not run"
        else:
            runs = within
            why = ("after job 1, the job's estimate with the margin is within the allowance read before it" if runs
                   else "after job 1, the job's estimate with the margin exceeds the allowance read before it: the job does not run")
    rec = {"job": job, "computed_utc": now(), "usage_read": u, "estimate": est, "margins_all_jobs_s": margins,
           "previous_job_final_status": final_status_of(job - 1) if job > 1 else None,
           "decision": {"runs": runs, "plan": plan, "within_allowance_this_job": within,
                        "rule": "t20-rule.md section 2, 'The allowance, and which job gives way'", "reason": why}}
    p.write_text(json.dumps(rec, indent=1))
    log(f"decision for job {job} recorded before its build: remaining {u['remaining_s']} s at {u['read_utc']}; estimate {est['expected_s']:.1f} s, "
        f"with the margin {est['with_margin_s']:.1f} s (IBM's formula {est['beside_ibm_formula_s']:.1f} s); runs {runs}")
    return rec


# --------------------------------------------------------------------------- the live run


# --------------------------------------------------------------------------- the fetch (hw_t10)
def spans_record(res):
    """The result's execution metadata, saved whole (hw_t10.spans_record)."""
    md = res.metadata or {}
    spans = list((md.get("execution") or {}).get("execution_spans") or [])
    rows = []
    for si, s in enumerate(spans):
        pubs = sorted(int(p) for p in s.pub_idxs)
        rows.append({"span": si, "start_utc": s.start.isoformat(), "stop_utc": s.stop.isoformat(), "duration_s": s.duration, "size_shots": int(s.size),
                     "positions": pubs, "shots_per_position": {str(p): int(np.asarray(s.mask(p)).sum()) for p in pubs}, "type": type(s).__name__})

    def js(v):
        if isinstance(v, dict):
            return {str(k): js(x) for k, x in v.items()}
        if isinstance(v, (list, tuple)):
            return [js(x) for x in v]
        if isinstance(v, (int, float, bool, str)) or v is None:
            return v
        return str(v)
    return {"present": bool(spans), "metadata_keys": sorted(md.keys()), "execution_keys": sorted((md.get("execution") or {}).keys()),
            "metadata_other": js({k: v for k, v in md.items() if k != "execution"}), "execution_spans": rows,
            "pub_metadata": [js(res[i].metadata) for i in range(len(res))]}


def fetch(job, job_id, M_):
    svc = service()
    j = svc.job(job_id)
    st = str(j.status())
    log(f"job {job} {job_id} status {st}")
    sub = json.loads((HERE / f"submit-t20-job{job}.json").read_text())
    assert sub["job_id"] == job_id
    if any(f in st for f in ("ERROR", "CANCELLED")):
        try:
            msg = str(j.error_message())
        except Exception as e:
            msg = type(e).__name__
        rec = {"job": job, "job_id": job_id, "status": "ERROR" if "ERROR" in st else "CANCELLED", "status_raw": st, "recorded_utc": now(),
               "error_message": msg, "note": "recorded and never resubmitted (t20-rule.md section 2); the verdicts that depend on it are not given"}
        (HERE / f"failed-t20-job{job}.json").write_text(json.dumps(rec, indent=1))
        record_stamp(svc.backend(BACKEND), f"job {job} after final status", st)
        sys.exit(f"job {job} ended {st}; recorded in failed-t20-job{job}.json; never resubmitted")
    if "DONE" not in st:
        sys.exit("not done; nothing written")
    res = j.result()
    counts = [res[k].data.c.get_counts() for k in range(len(sub["labels"]))]
    try:
        ex = spans_record(res)
    except Exception as e:
        ex = {"present": False, "error": type(e).__name__}
    mt = j.metrics()
    use = mt.get("usage") or {}
    for x in use.get("details", []):
        (x.get("metric") or {}).pop("id", None)
    try:
        opts = j.inputs.get("options")
    except Exception:
        opts = None
    after = record_stamp(svc.backend(BACKEND), f"job {job} after fetch", st)
    out = {"meta": M_, "job": job, "job_id": job_id, "backend": BACKEND, "qubit": QUBIT, "dt_s": sub["dt_s"], "waits": sub["waits"],
           "timestamps": mt.get("timestamps"), "usage": use, "job_options_as_recorded_by_ibm": opts,
           "calibration_at_submission": sub["calibration_at_submission"], "calibration_after_fetch": after["stamp_raw"],
           "fetched_utc": after["utc"], "labels": sub["labels"], "shots": sub["shots"], "counts": counts,
           "result_length_equals_positions": len(res) == len(sub["labels"]), "execution_metadata": ex}
    (HERE / f"results-t20-job{job}-counts.json").write_text(json.dumps(out, default=str))
    log(f"job {job} fetched {len(counts)} positions; execution metadata saved {ex.get('present')} ({len(ex.get('execution_spans', []))} spans); "
        f"recorded machine time {use.get('qpu_charge_time_seconds')} s; calibration after {after['stamp_raw']}; options by IBM {opts}")


# --------------------------------------------------------------------------- the dry run
def dryrun(M_):
    """Every job's build and every check on FakeFez, offline: nothing submitted."""
    from qiskit_ibm_runtime.fake_provider import FakeFez
    b = FakeFez()
    out, ok_all = {}, True
    for job in (1, 2, 3):
        circ, info, recs, circs, labels, shots, lim, waits, order, ok = built(b, job)
        smp, sopt, sgood = sampler_for(b, job)
        out[str(job)] = {"summary": summary(recs), "checks": recs, "order_checks": order, "limits": lim, "sampler_options": sopt, "waits": waits,
                         "n_positions": len(circs), "shots": sum(shots), "first_labels": labels[:6], "digests": digests(circ),
                         "estimate": estimate(job, sum(shots)), "all_pass": ok and sgood}
        ok_all = ok_all and ok and sgood
        log(f"dry run on {b.name}, job {job}: {summary(recs)}; order {order['pass']}; {len(circs)} positions, {sum(shots)} shots; limits {lim}; "
            f"sampler {sopt}; scheduled waits equal to requested {all(abs(w['difference_us'][q]) < 1e-9 for w in waits for q in QUADS)}; all {ok and sgood}")
    same = out["2"]["digests"] == out["3"]["digests"]
    rec = {"meta": M_, "backend": b.name, "dt_s": b.dt, "granularity": getattr(b.target, "granularity", 1) or 1, "runs": out,
           "jobs_2_and_3_same_circuits": same, "all_pass": ok_all and same}
    (HERE / "dryrun-t20.json").write_text(json.dumps(rec, indent=1, default=str))
    if not rec["all_pass"]:
        sys.exit("dry run: a check failed")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--dryrun", action="store_true")
    ap.add_argument("--go", action="store_true")
    ap.add_argument("--inputs", metavar="RULE_SHA256")
    for j in (1, 2, 3):
        for f in ("decision", "check", "submit"):
            ap.add_argument(f"--{f}{j}", action="store_true")
        ap.add_argument(f"--fetch{j}")
    a = ap.parse_args()
    M_ = meta()
    if a.inputs:
        inp = inputs_static(a.inputs)
        old = recorded("inputs.json") or {}
        if "jobs" in old:
            inp["jobs"] = old["jobs"]
        (HERE / "inputs.json").write_text(json.dumps(inp, indent=1))
        m = inp["manacitra"]
        log(f"inputs: manacitra {m['tag']} at {COMMIT} (tag resolves to {m['tag_resolves_to']}), installed equal to the archive {m['installed_equals_archive']}; "
            f"fit code v0.8.0 at {inp['fit_code']['tag_resolves_to']}; rule sha256 matches {inp['rule']['matches']} ({inp['rule']['size_bytes']} bytes); "
            f"reused code unchanged {inp['reused_unchanged']}")
        if not (inp["rule"]["matches"] and all(inp["reused_unchanged"].values()) and m["commit_present"] == "commit"
                and m["tag_resolves_to"] == COMMIT and m["installed_equals_archive"]):
            sys.exit("STOP: the rule, the package, the commit or the reused code differs from what the runner prompt names")
    if not a.inputs and not (recorded("inputs.json") or {}).get("rule", {}).get("matches"):
        sys.exit("STOP: the rule's hash has not been confirmed")
    if a.dryrun:
        dryrun(M_)
    for j in (1, 2, 3):
        if getattr(a, f"decision{j}"):
            write_decision(j)
        if getattr(a, f"check{j}"):
            live(a, M_, j, True)
        if getattr(a, f"submit{j}"):
            live(a, M_, j, False)
        if getattr(a, f"fetch{j}"):
            fetch(j, getattr(a, f"fetch{j}"), M_)

