"""Test 20, job 1 (the scan): the analysis t20-rule.md section 3 fixes for job 1, written before any job of this test
existed. Test 11 day 3's analyse_t11_day3.py, its job 1 part, unchanged in what it computes; its monitor part is not
here (jobs 2 and 3 are analyse_t20_monitors.py's). The only changes:
  - the bootstrap seed is 20304 (t20-rule.md section 2: "the bootstrap of 2,000 draws with seed 20304"); every other
    seed is test 11's job 1 fit seed as rulings-t11.md item 1 set it ("the same fits");
  - the verdict words are CONFIRMED ON THE FIFTH DATE if the package returns TWO FIXED FREQUENCIES, else NOT CONFIRMED
    ON THE FIFTH DATE;
  - delta, b and their intervals are set beside those of 16 October (test 7, day 1's numbers and the archived record),
    17 October (test 11 day 2, fits-t11.json) and 19 October (test 11 day 3, fits-t11-day3.json), each file checked
    by its SHA-256 before it is read;
  - the R0 of section 2 is reported as P_fit_at_5p6_us (A exp(-5.6 / tau') from the P fit, test 11's formula); the
    monitor analysis uses it only if the verdict is CONFIRMED ON THE FIFTH DATE, else 0.4770;
  - the section 3 note: if the verdict is NOT CONFIRMED or 2 delta differs from 89.6 kHz by more than 9 kHz, the
    fits carry the note that 5.6 us is no longer the antiphase wait as measured that day; the note changes no word;
  - test 11's model counts and its bets on Model 01 version 2 are not here (t20-rule.md section 3: not read);
  - the weight changes across job 1's span boundaries (test 11's ruling item 3) are kept as computed, beside, no word.

The per-span weights (amendment A26) are written under span_readings_A26.weight_per_span, once in the file, which is
where Sandhi 4.1's read_a26 looks (calibration_v4_1.py, lines 149 to 166; rulings-t20.md, ruling 1).

Usage: python -B analyse_t20_job1.py [--dir DIR] [--prefix t20] [--out fits-t20-job1.json]
  --prefix names the record's files (submit-PREFIX-job1.json, results-PREFIX-job1-counts.json, stamps-PREFIX.csv); the
  rehearsal on test 11 day 3's archived job uses --prefix t11-day3.
Never prints account details."""
from __future__ import annotations

import sys

sys.dont_write_bytecode = True

import argparse  # noqa: E402
import csv  # noqa: E402
import hashlib  # noqa: E402
import json  # noqa: E402
import math  # noqa: E402
import time  # noqa: E402
from datetime import datetime  # noqa: E402
from pathlib import Path  # noqa: E402

import numpy as np  # noqa: E402

HERE = Path(__file__).resolve().parent
SRC = HERE / "src-09bdebd"
sys.path.insert(0, str(SRC / "src"))
sys.path.insert(0, str(SRC / "tests"))
sys.path.insert(0, str(HERE))
import manacitra  # noqa: E402
from manacitra import archive as ar  # noqa: E402
import _reuse_runs as reuse  # noqa: E402
import monitor_t11 as MON  # noqa: E402

SEEDS = {"S_starts": 7302, "P_random_starts": 7303, "bootstrap": 20304, "T_random_starts": 7305, "periodogram_noise": 7306}
FIT_COMMIT = "09bdebdb0d9be9b4e582ff598869e7d156237aa5"
W_CHANGE = 0.10
R0_FALLBACK = 0.4770
SPLIT_REF_KHZ, SPLIT_TOL_KHZ = 89.6, 9.0
PREFIX = "t20"
DAY1 = {"date": "16 October 2026", "test": "test 7", "delta_ci90_kHz": [44.7, 44.9], "b_ci90": [0.333, 0.377],
        "weight_per_span": [0.457, 0.315, 0.274]}
EARLIER = {"17 October 2026": ("test 11 day 2", HB / "t11" / "fits-t11.json", "9390aaa0c4f87f2206adb1fb654f2c527c93712b11b6aab42a10ac2d7533a863", "day2"),
           "19 October 2026": ("test 11 day 3", HB / "t11-day3" / "fits-t11-day3.json", "001562473bcdda662247c2db544eddb2c9088b01a905ee4948a9612e20c0465e", "day3")}
BESIDE = None


def earlier_beside():
    """Delta, b and their intervals on 16, 17 and 19 October, the later two read from their hand-back fits files, each
    checked by its SHA-256 first."""
    out = {"16 October 2026": DAY1}
    for date, (test, p, want, key) in EARLIER.items():
        if hashlib.sha256(p.read_bytes()).hexdigest() != want:
            sys.exit(f"STOP: {p.name} differs from its recorded SHA-256")
        j1 = json.loads(p.read_text())["jobs"]["1"]
        b = j1["beside_day1"]
        out[date] = {"test": test, "source": str(p.relative_to(HB.parent.parent)), "sha256": want, "verdict": j1["verdict"],
                     "delta_kHz": b[f"delta_kHz_{key}"], "delta_ci90_kHz": b[f"delta_ci90_kHz_{key}"], "b": b[f"b_{key}"], "b_ci90": b[f"b_ci90_{key}"],
                     "held_out_error_S": b[f"held_out_error_S_{key}"], "held_out_error_P": b[f"held_out_error_P_{key}"],
                     "weight_per_span": [r["weighted_mean"] for r in (j1["span_readings_A26"].get("weight_per_span") or [])]}
    return out


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def load(d, name):
    p = d / name
    return json.loads(p.read_text()) if p.exists() else None


def ones_of(cts):
    return sum(v for k, v in cts.items() if k[-1] == "1")


def stamps_rows(d):
    p = d / f"stamps-{PREFIX}.csv"
    return list(csv.DictReader(p.open())) if p.exists() else []


def job_rows(rows, job):
    """The calibration record's rows for one job, from its build to its fetch, with the submission row's kind written as
    test 7's record wrote it ("submission ..."), which the repository's reader looks for."""
    out = []
    for r in rows:
        k = r["kind"]
        if k.startswith(f"job {job} "):
            r = dict(r)
            r["kind"] = k[len(f"job {job} "):]
            out.append(r)
    return out


def spans_of(rec):
    ex = rec.get("execution_metadata") or {}
    return ex.get("execution_spans") or []


def ts(s):
    return datetime.fromisoformat(s)


def readout(rec, labels_key="circuit"):
    out = {}
    for k in ("P10", "P01"):
        xs = [(ones_of(c), n) for lab, c, n in zip(rec["labels"], rec["counts"], rec["shots"]) if lab[labels_key] == k]
        o, n = sum(x[0] for x in xs), sum(x[1] for x in xs)
        p1 = o / n
        out[k] = {"P1": p1, "se": math.sqrt(p1 * (1 - p1) / n), "n": n, "per_circuit": [x[0] / x[1] for x in xs]}
    p10, p01 = out["P10"]["P1"], 1 - out["P01"]["P1"]
    return {"P1_given_0": p10, "P0_given_1": p01, "e": (p10 + p01) / 2, "circuits": out}


def published_at_submission(d, job):
    sub = load(d, f"submit-{PREFIX}-job{job}.json")
    if not sub:
        return None
    r = sub.get("stamp_row_at_submission") or {}
    keys = ("stamp_utc", "q143_readout_error", "q143_prob_meas1_prep0", "q143_prob_meas0_prep1", "q143_T1_us", "q143_T2_us")
    return {k: r.get(k) for k in keys}


# --------------------------------------------------------------------------- job 1
def analyse_job1(d, rec):
    rows = job_rows(stamps_rows(d), 1)
    doc = {"labels": rec["labels"], "counts": rec["counts"], "shots": rec["shots"], "timestamps": rec.get("timestamps"),
           "calibration_record": {"stamps": rows}}
    analysis, boot = reuse.t7_ramsey_xy(doc, SEEDS)
    readings = reuse.t7_readings(doc, analysis, SEEDS)
    doc["archived"] = {"readings_after_the_data": readings}
    sp = spans_of(rec)
    out = {"code": {"release": "v0.8.0", "commit": FIT_COMMIT, "manacitra_version_string": manacitra.__version__,
                    "functions": "_reuse_runs.t7_ramsey_xy, t7_readings, t7_spans, t7_span_readings; manacitra.wait.ramsey_xy_fit"},
           "seeds": SEEDS, "package_verdict": analysis["verdict"],
           "verdict": "CONFIRMED ON THE FIFTH DATE" if analysis["verdict"] == "TWO FIXED FREQUENCIES" else "NOT CONFIRMED ON THE FIFTH DATE",
           "analysis": analysis, "readings_after_the_data": readings, "bootstrap_meta": boot.get("meta")}
    dec = analysis["deciding"]
    P = analysis["fits"]["P"]["params"]
    out["this_date"] = {"delta_kHz": P["delta_MHz"] * 1e3, "delta_ci90_kHz": dec["delta_ci90_kHz"], "split_2delta_kHz": 2 * P["delta_MHz"] * 1e3,
                        "b": P["b"], "b_ci90": dec["b_ci90"], "held_out_error_S": dec["held_out_error_S"], "held_out_error_P": dec["held_out_error_P"]}
    out["beside_earlier_dates"] = BESIDE
    try:
        d1 = ar.load("ibm_fez/t7-ramsey-xy.json")["archived"]["analysis"]
        out["beside_16_october_archived"] = {"verdict": d1["verdict"], "deciding": d1["deciding"], "fits": d1["fits"]}
    except Exception as e:
        out["beside_16_october_archived"] = {"error": type(e).__name__}
    if sp:
        spans = {"spans": sp, "n_positions": len(rec["labels"])}
        out["spans_derived"] = reuse.t7_spans(spans)
        sr = reuse.t7_span_readings(doc, spans)
        out["span_readings_A26"] = sr
        changes = {}
        for name, b in sr["span_boundaries"].items():
            bw = [x["weight"] for x in b["before"]]
            aw = [x["weight"] for x in b["after"]]
            if len(bw) == 3 and len(aw) == 3:
                ch = float(np.mean(aw) - np.mean(bw))
                changes[name] = {"between_positions": b["between_positions"], "before": b["before"], "after": b["after"], "mean_before": float(np.mean(bw)),
                                 "mean_after": float(np.mean(aw)), "change": ch, "at_least_0p10": abs(ch) >= W_CHANGE}
            else:
                changes[name] = {"between_positions": b["between_positions"], "before": b["before"], "after": b["after"], "note": "fewer than three positions passing the lever on a side"}
        out["weight_changes_across_boundaries"] = {"rule": "the author's ruling: the plain mean of the three after minus the plain mean of the three before; 0.10 or more counts",
                                                   "boundaries": changes, "n_at_least_0p10": sum(1 for c in changes.values() if c.get("at_least_0p10")),
                                                   "n_boundaries": len(changes)}
    else:
        out["spans_derived"] = None
        out["span_readings_A26"] = {"note": "no execution metadata saved with the counts; to be retrieved again before analysis"}
    out["P_fit_at_5p6_us"] = P["A"] * math.exp(-MON.WAIT_US / P["tau_prime_us"])
    out["antiphase_wait_from_this_dates_split_us"] = 1.0 / (4 * P["delta_MHz"])
    split = 2 * P["delta_MHz"] * 1e3
    moved = out["verdict"] != "CONFIRMED ON THE FIFTH DATE" or abs(split - SPLIT_REF_KHZ) > SPLIT_TOL_KHZ
    out["lines_moved_note"] = {"applies": moved, "split_2delta_kHz": split, "reference_kHz": SPLIT_REF_KHZ, "tolerance_kHz": SPLIT_TOL_KHZ,
                               "rule": "t20-rule.md section 3, 'If the lines have moved': the note is not a verdict and changes no word",
                               "text": "5.6 us is no longer the antiphase wait of the qubit as measured that day" if moved else None}
    out["readout"] = {"measured": readout(rec), "published_at_submission": published_at_submission(d, 1)}
    return out


def main():
    global PREFIX, BESIDE
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", default=str(HERE))
    ap.add_argument("--prefix", default="t20")
    ap.add_argument("--out", default="fits-t20-job1.json")
    a = ap.parse_args()
    d, PREFIX = Path(a.dir), a.prefix
    t0 = time.time()
    BESIDE = earlier_beside()
    out = {"meta": {"script_sha256": sha(__file__), "monitor_t11_sha256": sha(HERE / "monitor_t11.py"), "fit_commit": FIT_COMMIT, "seeds_job1": SEEDS,
                    "record_prefix": PREFIX, "computed_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}, "jobs": {}}
    r1 = load(d, f"results-{PREFIX}-job1-counts.json")
    if r1:
        j1 = analyse_job1(d, r1)
        j1["job_id"] = r1.get("job_id")
        out["jobs"]["1"] = j1
        confirmed = j1["verdict"] == "CONFIRMED ON THE FIFTH DATE"
        out["R0"] = {"value": j1["P_fit_at_5p6_us"] if confirmed else R0_FALLBACK,
                     "from": "job 1's P fit at 5.6 us (job 1 returned TWO FIXED FREQUENCIES)" if confirmed
                     else "0.4770, as test 18 used it (job 1 did not return TWO FIXED FREQUENCIES); the weight series carries that caveat",
                     "caveat": not confirmed}
    else:
        out["jobs"]["1"] = {"verdict": None, "note": (load(d, f"failed-{PREFIX}-job1.json") or load(d, f"decision-{PREFIX}-job1.json") or {"note": "no counts"})}
        out["R0"] = {"value": R0_FALLBACK, "from": "0.4770, as test 18 used it (job 1 did not run or returned no counts); the weight series carries that caveat", "caveat": True}
    out["meta"]["elapsed_s"] = time.time() - t0
    (d / a.out).write_text(json.dumps(out, default=str))
    n_a26 = json.dumps(out, default=str).count('"span_readings_A26"')
    j1 = out["jobs"]["1"]
    print(json.dumps({"verdict": j1.get("verdict"), "this_date": j1.get("this_date"), "R0": out["R0"], "lines_moved_note": (j1.get("lines_moved_note") or {}).get("applies"),
                      "weight_per_span": [r.get("weighted_mean") for r in ((j1.get("span_readings_A26") or {}).get("weight_per_span") or [])],
                      "span_readings_A26_keys_in_file": n_a26, "elapsed_s": round(out["meta"]["elapsed_s"], 1)}, indent=1, default=str))


if __name__ == "__main__":
    main()

analyse_t20_monitors.py.text:
"""Test 20, jobs 2 and 3 (the monitor at 5.6 us): the analysis from the counts t20-rule.md section 3 fixes for them,
written before any job of this test existed. Test 18's analyse_t18.py, unchanged in what it computes, with only these
changes:
  - the jobs are keyed job2 and job3, read from results-t20-jobN-counts.json and submit-t20-jobN.json;
  - R0 is section 2's: read from job 1's fits (fits-t20-job1.json, its "R0" block): job 1's P fit at 5.6 us if job 1
    returned TWO FIXED FREQUENCIES, else 0.4770 as test 18 used it, with the caveat recorded beside every weight;
  - the gap between the jobs is monitor_t11.gap on job 2 and job 3 (its own keys; no relabelling);
  - the weight per span is set beside test 11 day 3's monitor jobs, test 17's B1 and test 18's two jobs, with the
    hours between (beside, no word);
  - section 3's note (5.6 us no longer the antiphase wait as measured that day) is copied from job 1's fits beside the
    words, and changes no word.
Test 12's steps 1 to 10 (monitor_t12.analyse_job, byte-identical copy of test 12's file, unchanged) at 1,000 shots and
148 repeats; test 11's phase and weight words and test 12's level word per job; test 11's pooled words over the two
jobs and the phase difference across the gap between them, beside. Test 11's bets on Model 01 version 2 are not read.

Usage: python -B analyse_t20_monitors.py [--dir DIR] [--job1-fits fits-t20-job1.json] [--out fits-t20-counts.json]
       [--keys job2,job3] [--file-pattern results-t20-{key}-counts.json] [--submit-pattern submit-t20-{key}.json]
Never prints account details."""
from __future__ import annotations

import sys

sys.dont_write_bytecode = True

import argparse  # noqa: E402
import hashlib  # noqa: E402
import json  # noqa: E402
import math  # noqa: E402
import time  # noqa: E402
from datetime import datetime  # noqa: E402
from pathlib import Path  # noqa: E402

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import monitor_t12 as MON  # noqa: E402
import monitor_t11 as M11  # noqa: E402  test 11's pooled words and gap, unchanged

R0 = None            # set in main() from job 1's fits, t20-rule.md section 2
R0_FALLBACK = 0.4770
R0_RECORD = None
SHOTS = 1000
N_REP = 148


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def ts(s):
    return datetime.fromisoformat(s.replace("Z", "+00:00")) if s.endswith("Z") else datetime.fromisoformat(s)


def ones_of(cts):
    return sum(v for k, v in cts.items() if k[-1] == "1")


def runs(idx):
    out = []
    for i in sorted(idx):
        if out and i == out[-1][1] + 1:
            out[-1][1] = i
        else:
            out.append([i, i])
    return out


def beside_weights(running):
    out = {}
    f = json.loads(D3_FITS.read_text()) if D3_FITS.exists() else None
    if f:
        for j in ("2", "3"):
            ps = f["jobs"][j]["weight"]["per_span"]
            rj = (f["jobs"][j].get("timestamps") or {}).get("running")
            out[f"t11-day3-job{j}"] = {"w_per_span": [s.get("mean_w") for s in ps], "running_utc": rj, "source": "tests/handback/t11-day3/fits-t11-day3.json",
                                       "hours_before_this_job": (ts(running) - ts(rj)).total_seconds() / 3600 if (running and rj) else None}
    f = json.loads(T17_FITS.read_text()) if T17_FITS.exists() else None
    if f and "B1" in f["jobs"]:
        j = f["jobs"]["B1"]
        rj = (j.get("timestamps") or {}).get("running")
        out["t17-B1"] = {"w_per_span": [s.get("mean_w") for s in j["analysis"]["weight_per_span"]], "running_utc": rj, "source": "tests/handback/t17/fits-t17-counts.json",
                         "hours_before_this_job": (ts(running) - ts(rj)).total_seconds() / 3600 if (running and rj) else None}
    f = json.loads(T18_FITS.read_text()) if T18_FITS.exists() else None
    if f:
        for k in ("job1", "job2"):
            j = f["jobs"].get(k) or {}
            if "analysis" not in j:
                continue
            rj = (j.get("timestamps") or {}).get("running")
            out[f"t18-{k}"] = {"w_per_span": [s.get("mean_w") for s in j["analysis"]["weight_per_span"]], "running_utc": rj, "R0": j.get("R0"),
                               "source": "tests/handback/t18/fits-t18-counts.json",
                               "hours_before_this_job": (ts(running) - ts(rj)).total_seconds() / 3600 if (running and rj) else None}
    return out


def analyse(rec, sub=None):
    ex = rec.get("execution_metadata") or {}
    sp = ex.get("execution_spans") or []
    spans = [{"span": s["span"], "positions": s["positions"], "start": ts(s["start_utc"]), "stop": ts(s["stop_utc"]), "duration_s": s["duration_s"]} for s in sp]
    ones = [ones_of(c) for c in rec["counts"]]
    assert set(rec["shots"]) == {SHOTS}, "the shots differ from the rule's"
    assert max(l["repeat"] or 0 for l in rec["labels"]) == N_REP, "the repeats differ from the rule's"
    r = MON.analyse_job(ones, rec["labels"], spans, r0=R0, shots=SHOTS)
    order = sorted(sp, key=lambda s: s["start_utc"])
    rank = {s["span"]: i for i, s in enumerate(order)}
    span_of = {p: s["span"] for s in sp for p in s["positions"]}
    out_of_order, hi = [], -1
    for p in range(len(rec["labels"])):
        rk = rank.get(span_of.get(p), -1)
        if rk < hi:
            out_of_order.append({"position": p, "span": span_of.get(p), "after_a_position_in_span": order[hi]["span"]})
        hi = max(hi, rk)
    execution = {"n_spans": len(sp), "spans_in_start_order": [{"span": s["span"], "start_utc": s["start_utc"], "stop_utc": s["stop_utc"], "duration_s": s["duration_s"],
                                                               "position_runs": runs(s["positions"]), "n_positions": len(s["positions"]),
                                                               "every_position_all_its_shots": all(v == rec["shots"][int(q)] for q, v in s["shots_per_position"].items())} for s in order],
                 "gaps_s": [(ts(b["start_utc"]) - ts(x["stop_utc"])).total_seconds() for x, b in zip(order, order[1:])],
                 "repeat_period_s": r["repeat_period_s"], "repeats_per_span": r["repeats_per_span"], "straddling_repeats": r["straddling_repeats"],
                 "positions_run_out_of_submitted_order": out_of_order, "metadata_saved_at_fetch": ex.get("present")}
    ro = {}
    for k in ("P10", "P01"):
        xs = [(ones_of(c), n) for lab, c, n in zip(rec["labels"], rec["counts"], rec["shots"]) if lab["circuit"] == k]
        o, n = sum(x[0] for x in xs), sum(x[1] for x in xs)
        ro[k] = {"P1": o / n, "se": math.sqrt((o / n) * (1 - o / n) / n), "n": n, "per_circuit": [x[0] / x[1] for x in xs]}
    srow = (sub or {}).get("stamp_row_at_submission") or {}
    readout = {"P1_given_0": ro["P10"]["P1"], "P0_given_1": 1 - ro["P01"]["P1"], "e": (ro["P10"]["P1"] + 1 - ro["P01"]["P1"]) / 2, "circuits": ro,
               "published_at_submission": {k: srow.get(k) for k in ("stamp_utc", "q143_readout_error", "q143_prob_meas1_prep0", "q143_prob_meas0_prep1", "q143_T1_us", "q143_T2_us")}}
    running = (rec.get("timestamps") or {}).get("running")
    beside = {"this_job": [s.get("mean_w") for s in r["weight_per_span"]], "this_job_errors": [s.get("error") for s in r["weight_per_span"]],
              "earlier": beside_weights(running), "stamp_at_submission": srow.get("stamp_utc")}
    counts = {"span_boundaries_crossed": len(r["boundaries_crossed"]), "boundaries_not_crossed_by_whole_repeats": r["boundaries_not_crossed"],
              "level_changes": r["n_level_changes"], "level_change_sizes": [{k: x[k] for k in ("spans", "difference", "error", "in_errors", "level_change")} for x in r["level_changes"]],
              "phase_switches_at_boundary_pairs": r["n_boundary"], "phase_switches_within_spans": r["n_within"],
              "weight_switches_at_boundary_pairs": r["n_boundary_w"], "weight_switches_within_spans": r["n_within_w"],
              "within_span_time_s": r["within_time_s"]}
    return {"job_id": rec.get("job_id"), "timestamps": rec.get("timestamps"), "R0": R0, "R0_record": R0_RECORD, "shots": SHOTS, "repeats": N_REP,
            "verdicts": r["verdicts"], "analysis": {k: v for k, v in r.items() if k not in ("repeats", "pairs")}, "pairs": r["pairs"],
            "series": {"k": [x["k"] for x in r["repeats"]], "span": [x["span"] for x in r["repeats"]], "straddles": [x["straddles"] for x in r["repeats"]],
                       "P_X": [x["PX"] for x in r["repeats"]], "P_Y": [x["PY"] for x in r["repeats"]], "theta": [x["theta"] for x in r["repeats"]],
                       "phi_unwrapped": [x["phi"] for x in r["repeats"]], "r": [x["r"] for x in r["repeats"]], "sigma": [x["sigma"] for x in r["repeats"]],
                       "s": [x["s"] for x in r["repeats"]], "w": [x["w"] for x in r["repeats"]], "se_w": [x["se_w"] for x in r["repeats"]],
                       "branch": [x["branch"] for x in r["repeats"]]},
            "execution_record": execution, "readout": readout, "weight_per_span_beside": beside, "scheduled_wait": rec.get("waits"),
            "counts_of_the_run": counts}, r


def main():
    global R0, R0_RECORD
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", default=str(HERE))
    ap.add_argument("--job1-fits", default="fits-t20-job1.json")
    ap.add_argument("--out", default="fits-t20-counts.json")
    ap.add_argument("--keys", default="job2,job3")
    ap.add_argument("--file-pattern", default="results-t20-{key}-counts.json")
    ap.add_argument("--submit-pattern", default="submit-t20-{key}.json")
    a = ap.parse_args()
    d = Path(a.dir)
    t0 = time.time()
    jf = d / a.job1_fits
    if jf.exists():
        f1 = json.loads(jf.read_text())
        R0_RECORD = dict(f1["R0"], job1_fits=jf.name, job1_fits_sha256=sha(jf), job1_verdict=f1["jobs"]["1"].get("verdict"),
                         lines_moved_note=f1["jobs"]["1"].get("lines_moved_note"))
    else:
        R0_RECORD = {"value": R0_FALLBACK, "from": "0.4770, as test 18 used it (no fits of job 1); the weight series carries that caveat", "caveat": True,
                     "job1_fits": None, "lines_moved_note": None}
    R0 = float(R0_RECORD["value"])
    out = {"meta": {"script_sha256": sha(__file__), "monitor_t12_sha256": sha(HERE / "monitor_t12.py"), "monitor_t11_sha256": sha(HERE / "monitor_t11.py"),
                    "phase_t10_sha256": sha(HERE / "phase_t10.py"), "R0": R0, "R0_record": R0_RECORD, "median_phase_reading": MON.MEDIAN_PHASE,
                    "computed_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                    "reading": "t20-rule.md section 3: test 12's steps 1 to 10 at 1,000 shots, 148 repeats and the R0 of section 2; test 11's phase and weight words and test 12's level word per job; test 11's pooled words over the two jobs and the phase difference across the gap beside; test 11's bets on Model 01 version 2 not read"},
           "jobs": {}}
    summary, mons, recs = {}, {}, {}
    for key in a.keys.split(","):
        p = d / a.file_pattern.format(key=key)
        if not p.exists():
            out["jobs"][key] = {"note": "no counts file: the job did not run, or its end is recorded"}
            continue
        rec = json.loads(p.read_text())
        sp = d / a.submit_pattern.format(key=key)
        sub = json.loads(sp.read_text()) if sp.exists() else None
        res, r = analyse(rec, sub)
        res["counts_file_sha256"] = sha(p)
        out["jobs"][key] = res
        mons[key], recs[key] = r, rec
        summary[key] = {"verdicts": r["verdicts"], "usable": r["usable"], "median_r": round(r["median_r"], 4),
                        "boundaries": [(b["spans"], b["pair"], b["repeats_between"]) for b in r["boundaries_crossed"]],
                        "weight_per_span": [(s.get("mean_w") and round(s["mean_w"], 4), s.get("error") and round(s["error"], 4), s["n_whole_repeats"]) for s in r["weight_per_span"]],
                        "level_changes": [(round(x["difference"], 4), round(x["error"], 4), round(x["in_errors"], 1), x["level_change"]) for x in r["level_changes"]]}
    # t20-rule.md section 3, beside: test 11's pooled words and the phase across the gap
    keys = [k for k in a.keys.split(",") if k in mons]
    usable = [k for k in keys if mons[k]["usable"]]
    pv = [mons[k]["verdicts"]["phase"] for k in usable]
    wv = [mons[k]["verdicts"]["weight_by_pairs"] for k in usable]
    out["beside_test11_pooled"] = {"jobs": usable, "phase": M11.pooled(pv) if len(usable) == 2 else None,
                                   "weight": M11.pooled_weight(wv) if len(usable) == 2 and all(wv) else None,
                                   "note": "test 11's pooling over the two monitor jobs (t20-rule.md section 3); given only when both jobs are read"}
    if len(keys) == 2:
        g = M11.gap(mons[keys[0]], mons[keys[1]])
        sp1 = recs[keys[0]]["execution_metadata"]["execution_spans"]
        sp2 = recs[keys[1]]["execution_metadata"]["execution_spans"]
        g["gap_s_from_the_execution_records"] = (min(ts(s["start_utc"]) for s in sp2) - max(ts(s["stop_utc"]) for s in sp1)).total_seconds()
        g["note"] = "monitor_t11.gap (test 11's code, unchanged), on job 2 against job 3"
        out["beside_test11_gap_between_jobs"] = g
        summary["gap"] = {k: g[k] for k in ("d_phase", "se_phase", "phase_differs_by_more_than_5_se", "gap_s_from_the_execution_records")}
    else:
        out["beside_test11_gap_between_jobs"] = {"note": "not available: two jobs were not read"}
    summary["pooled"] = {k: out["beside_test11_pooled"][k] for k in ("phase", "weight")}
    out["R0"] = R0_RECORD
    out["lines_moved_note"] = R0_RECORD.get("lines_moved_note")
    summary["R0"] = {k: R0_RECORD.get(k) for k in ("value", "from", "caveat")}
    out["meta"]["elapsed_s"] = time.time() - t0
    (d / a.out).write_text(json.dumps(out, default=str))
    print(json.dumps(summary, indent=1, default=str))


if __name__ == "__main__":
    main()

scorer_beside_t20.py.text:
"""Test 20, section 6: the scorer's test 15 readings set beside this rule's (fits-t20-shots.json), on both monitor jobs,
quantity by quantity (scorer_beside_t18.py, the test's names changed): per span the sharing ratio and word,
the threshold, the duty, the tau_c lag and seconds, the telegraph sd, the quarter-span duties, the mid-sweep fraction,
the switches and dwells, the whole repeats and the duration; per boundary within a job the duties' difference, the
combined sd, the ratio and the word; between the two jobs the job mean duties, their difference, the combined sd, the
ratio and the word, beside test 15's between_jobs row. Equal means within 1e-9. Reported, no word.
Usage: python -I -B scorer_beside_t20.py [HANDBACK_DIR, for the rehearsal only]"""
import json
import math
import sys
from pathlib import Path

KEYS = ["ratio", "word_of_the_ratio", "threshold", "duty_b", "lag_1_over_e", "tau_c_sweeps_used", "tau_c_s", "telegraph_sd", "quarter_span_duties",
        "mid_sweep_fraction_middle_fifth", "switches", "dwell_high_s", "dwell_low_s", "n_rows", "duration_s", "duty_b_at_threshold_20_80",
        "telegraph_sd_at_threshold_20_80"]


def eq(a, b):
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(eq(x, y) for x, y in zip(a, b))
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return math.isclose(a, b, rel_tol=0, abs_tol=1e-9)
    return a == b


def main():
    sc = json.loads((HB / "scorecard-t20.json").read_text())
    ours = json.loads((HB / "fits-t20-shots.json").read_text())
    rows, brows, jrows, n, same = [], [], [], 0, 0
    for sj in sc["jobs"]:
        key = sj["key"]
        wd = ours["jobs"][key]["qubits"]["143"]["waits"]["monitor"]
        q = wd["quadrature_of_record"]
        mine = {s["span"]: s[q] for s in wd["spans"] if q in s}
        for x in sj["series"]:
            t = x["t15"]
            m = mine.get(x["span"])
            for k in KEYS:
                if k in t or (m and k in m):
                    a, b = t.get(k), (m or {}).get(k)
                    e = eq(a, b)
                    n += 1
                    same += e
                    if not e:
                        rows.append({"job": key, "span": x["span"], "quantity": k, "scorer": a, "this_rule": b})
    ob = {(b["job"], tuple(b["spans"])): b for b in ours["boundaries"]}
    for b in sc["boundaries"]:
        o = ob.get((b["job"], tuple(b["spans"])))
        for k in ("difference", "combined_sd", "ratio", "word"):
            a, c = b["test15"].get(k), (o or {}).get(k)
            e = eq(a, c)
            n += 1
            same += e
            if not e:
                brows.append({"job": b["job"], "spans": b["spans"], "quantity": k, "scorer": a, "this_rule": c})
    for b in sc.get("between_jobs", []):
        o = next((r for r in ours.get("between_jobs", []) if r["jobs"] == b["jobs"]), None)
        pairs = (("job_mean_threshold_duties", "job_mean_w_duties"), ("difference", "difference"), ("combined_sd", "combined_sd"), ("ratio", "ratio"), ("word", "word"))
        for ks, ko in pairs:
            a, c = b.get(ks), (o or {}).get(ko)
            e = eq(a, c)
            n += 1
            same += e
            if not e:
                jrows.append({"jobs": b["jobs"], "scorer_quantity": ks, "this_rule_quantity": ko, "scorer": a, "this_rule": c})
    out = {"quantities_compared": n, "equal": same, "differences": rows + brows + jrows,
           "note": "the scorer's between-jobs row takes the job means of the threshold duty b; test 15's between_jobs takes them on the weight's branch; where w is b on every span the two agree",
           "scorer_quadrature_of_record": sorted({json.dumps(x["quadrature_of_record"], sort_keys=True) for sj in sc["jobs"] for x in sj["series"]})}
    (HB / "scorer-beside-t20.json").write_text(json.dumps(out, indent=1, default=str))
    print(json.dumps({k: out[k] for k in ("quantities_compared", "equal", "scorer_quadrature_of_record")}), json.dumps(out["differences"][:12], default=str))


if __name__ == "__main__":
    if len(sys.argv) > 1:
        HB = Path(sys.argv[1]).resolve()
    main()

